var vectaSyncInFlight=false,vectaSyncProgress=null;
function updateConnectivityUI(state){var el=document.getElementById('vectaConnectivity'),txt=document.getElementById('vectaConnectivityText'),banner=document.getElementById('vectaOfflineBanner');if(!el||!txt)return;var pending=vectaPendingSync().length;if(state==='syncing'){el.className='vectaConnectivity syncing';var done=vectaSyncProgress&&Number(vectaSyncProgress.done||0),total=vectaSyncProgress&&Number(vectaSyncProgress.total||0);txt.textContent=total?('Synchronising workshop dataâ€¦ '+done+' of '+total):'Synchronising workshop dataâ€¦';if(banner)banner.classList.remove('show');return}if(state==='checking'||vectaCloudReachable===null){el.className='vectaConnectivity syncing';txt.textContent='Checking cloud connectionâ€¦';if(banner)banner.classList.remove('show');return}var online=navigator.onLine&&vectaCloudReachable;if(online){el.className='vectaConnectivity online';var failed=pending&&vectaPendingSync().some(function(x){return Number(x.attempts||0)>0&&x.last_error});txt.textContent=pending?('Online Â· '+pending+' change'+(pending===1?'':'s')+(failed?' still need sync â€” retrying':' waiting to sync')):'Online Â· workshop data protected';if(banner)banner.classList.remove('show')}else{el.className='vectaConnectivity offline';txt.textContent='Offline workshop mode'+(pending?' Â· '+pending+' queued':'');if(banner)banner.classList.add('show')}}
function vectaOpenBackupDb(){return new Promise(function(resolve,reject){if(!window.indexedDB)return reject(new Error('IndexedDB is unavailable.'));var settled=false,timer=setTimeout(function(){if(settled)return;settled=true;reject(new Error('Backup storage took too long to open.'))},2500),req=indexedDB.open(VECTA_BACKUP_DB,1);function fail(error){if(settled)return;settled=true;clearTimeout(timer);reject(error||new Error('Could not open backup store.'))}req.onupgradeneeded=function(){var db=req.result;if(!db.objectStoreNames.contains(VECTA_BACKUP_STORE))db.createObjectStore(VECTA_BACKUP_STORE,{keyPath:'id'})};req.onsuccess=function(){if(settled){try{req.result.close()}catch(e){}return}settled=true;clearTimeout(timer);resolve(req.result)};req.onerror=function(){fail(req.error)};req.onblocked=function(){fail(new Error('Backup storage is blocked by an older app window.'))}})}
